"""Prepare one new direct collocation model; no candidate/optimizer/IK/physics."""
import json,datetime,time
import numpy as np
from scipy import sparse
from low_seat_clock_transcription_444 import *
O=D/'clock_transcription_preparation_444'

def main():
 launch=read(D/'clock_transcription_preparation_launch_444.json')
 for p,h in launch['source_input_sha256'].items():assert sha(p)==h,p
 O.mkdir(exist_ok=False);start=time.monotonic();s=load_inputs();g=graph(s)
 oracle=Mechanics(s,np.arange(1467));Y=oracle.values(s['X'])
 # Newly implemented oracle replay only. No geometry screen, root solve or
 # virtual-work audit is repeated. Save before any derivative/check assertion.
 np.savez_compressed(O/'primal_replay.npz',X=s['X'],Y=Y,reference_command=s['z']['command'][:,s['moving']],reference_torque=s['z']['torque'],reference_com=s['z']['com'],reference_equilibrium=s['z']['equilibrium'],reference_gap=np.array([r['pelvis_gap_m'] for r in s['records']]))
 errors=dict(command=float(abs(Y[:,15:31]-s['z']['command'][:,s['moving']]).max()),torque=float(abs(Y[:,31:47]-s['z']['torque']).max()),com=float(abs(Y[:,48:51]-s['z']['com']).max()),gap=float(abs(Y[:,47]-np.array([r['pelvis_gap_m'] for r in s['records']])).max()),feet=float(abs(Y[:,:12]).max()),moments=float(abs(Y[:,12:14]-s['z']['equilibrium'][:,1:]).max()),totalnormal=float(abs(Y[:,14]-s['z']['equilibrium'][:,0]).max()))
 (O/'primal_replay.json').write_text(json.dumps(errors,indent=2))
 assert errors['command']<2e-10 and errors['torque']<1e-8
 assert max(errors[k] for k in ['com','gap','feet','moments','totalnormal'])<2e-12,errors
 print(json.dumps(dict(stage='new_oracle_primal_replay',errors=errors,elapsed_s=time.monotonic()-start)),flush=True)
 # Six declared fixtures cover prelift, exact lift event, swing, the localized
 # normal-phase reversal, late normal approach, and fixed load endpoint.
 indices=np.array([1366,93,912,604,1300,658]);small=Mechanics(s,indices);x=s['X'][indices];J=small.jacobian(x);h=1e-6;FD=np.empty_like(J)
 for j in range(24):
  d=np.zeros_like(x);d[:,j]=h;FD[:,:,j]=(small.values(x+d)-small.values(x-d))/(2*h)
 per=np.max(abs(J-FD),axis=(1,2));v=np.sin(np.arange(24)+.37);directional=(small.values(x+h*v)-small.values(x-h*v))/(2*h);ad=np.einsum('nrc,c->nr',J,v)
 np.savez_compressed(O/'derivative_fixtures.npz',indices=indices,X=x,J=J,FD=FD,direction=v,FD_direction=directional,AD_direction=ad)
 error=float(per.max());dot_error=float(abs(ad-directional).max())
 assert max(error,dot_error)<2e-6,(error,dot_error)
 # Complete local block Jacobians are generated by AD, not central virtual
 # work columns. No inverse-gap root or feasibility correction is performed.
 fullJ=oracle.jacobian(s['X']);np.savez_compressed(O/'local_blocks.npz',J=fullJ)
 canonical=g['canonical'];ls=g['label_to_state'];K=len(canonical)
 order=np.argsort([float(t) for t in g['unique']]);representative=[next(i for i,t0 in enumerate(g['times']) if t0==t) for t in g['unique']]
 ordered_states=ls[representative];edge_a=ordered_states[:-1];edge_b=ordered_states[1:];positive=edge_a!=edge_b
 A=sparse.coo_matrix((np.r_[-np.ones(positive.sum()),np.ones(positive.sum())],(np.r_[np.arange(positive.sum()),np.arange(positive.sum())],np.r_[edge_a[positive],edge_b[positive]])),shape=(positive.sum(),K)).tocsr()
 clock_a=ls[:675];clock_b=ls[1:676]
 rate=sparse.coo_matrix((np.r_[-np.ones(675),np.ones(675)],(np.r_[np.arange(675),np.arange(675)],np.r_[clock_a,clock_b])),shape=(675,K)).tocsr()
 target=sparse.coo_matrix((np.r_[-9*np.ones(675),10*np.ones(675)],(np.r_[np.arange(675),np.arange(675)],np.r_[clock_a,clock_b])),shape=(675,K)).tocsr()
 sparse.save_npz(O/'monotone_incidence.npz',A);sparse.save_npz(O/'clock_rate_incidence.npz',rate);sparse.save_npz(O/'clock_target_incidence.npz',target)
 np.savez_compressed(O/'mesh.npz',canonical=canonical,label_to_state=ls,label_to_time=g['label_to_time'],ordered_representative=np.array(representative),ordered_states=ordered_states,edge_kept=positive,fixed=g['fixed'],inactive=g['inactive'],reference=s['X'][canonical],canonical_Y=Y[canonical],canonical_J=fullJ[canonical])
 times=[[str(t.numerator),str(t.denominator)] for t in g['times']]
 (O/'exact_times.json').write_text(json.dumps(times))
 # Future full assembly must retain ALL old node constraints and inward
 # buffers. This is intentionally a preparation, not a partially checked NLP.
 contract=dict(name='direct shared-clock persistent-contact transcription',input='saved complete440, explicitly infeasible rate/phase seed',labels=1467,exact_distinct_times=len(g['unique']),state_blocks=K,coordinates_per_block=24,coordinate_names=['root_x','root_y','descent_f','orientation_p']+[s['m'].names[j] for j in s['legs']]+['left_corner_'+str(i) for i in range(4)]+['right_corner_'+str(i) for i in range(4)],fixed_pose_blocks=int(g['fixed'].sum()),nominal_research_change='Replace optional piecewise-gap f-root and independent sample solves with direct whole-path collocation. Restore nominal orientation phase as a variable via a saved-reference rotation axis. Initial and104..114 load poses remain fixed. Feet and persistent local contact points stay prescribed, including explicitly retained330 approach frame drift.',timing='Exact existing event budgets[93,194,245,101,17];67520ms steps. Geometry, forces and monotone f/p progression are jointly variable against this clock. No fixed-command retiming or allocation search.25 synthetic holds are only algebraic equality, never CURRENT quiet permission.',equations='12 foot-frame,2 horizontal moment,1 total normal per state;12mm hover explicit. No gap equation chooses f between nodes.',required_inequalities=['original joint/command/effort bounds','nonnegative active corner loads; exact inactive zero','left support before and through lift-off','nondecreasing f AND p at every ordered state','actual gap ordering and6mm/s descent','all27708 original/support/window rows at115nodes','all1572 original coordinate bounds','all prior8eps contact-phase-support/4ULP per20ms rate/32ULP target reserves','uniform4302^-23 dimensionless buffer','675 exact clock rate and inverse-target rows','full sample geometry and a separately validated between-sample kinematic lift','actualfloat32 forwardfilter and current quiet/load/runtime guards before physical admission'],mandatory_events=[16,64,99,104,114],added_feedback_authority=0,physical_threshold_changes=0,complete_global_constraint_assembly=False,bounded_solver_specification_frozen=False,optimizer_launch_allowed=False)
 (O/'formulation.json').write_text(json.dumps(contract,indent=2))
 result=dict(utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),scope=__doc__,passed=True,primal_replay_errors=errors,derivative_fixtures=indices.tolist(),new_derivative_columns=144,maximum_new_local_derivative_error=error,maximum_directional_error=dot_error,unchanged_derivative_bound=2e-6,full_AD_blocks=1467,full_AD_output_rows=51,full_AD_coordinates=24,alias_max_coordinate_difference=g['alias_max_coordinate_difference'],exact_time_label_count=1467,exact_distinct_times=len(g['unique']),state_blocks=K,monotonic_edges=int(A.shape[0]),fixed_pose_blocks=int(g['fixed'].sum()),local_mechanics_preflight_only=True,complete_global_constraint_assembly=False,optimizer_launch_allowed=False,new_trajectory_constructed=False,root_solves=0,trajectory_optimizer_calls=0,actual_forward_filter_ticks=0,physics_ticks=0,policy_updates=0,physical_admission=False,elapsed_s=time.monotonic()-start)
 (O/'preparation.json').write_text(json.dumps(result,indent=2));(O/'SHA256.json').write_text(json.dumps({p.name:sha(p) for p in O.iterdir() if p.is_file()},indent=2));print(json.dumps(result,indent=2),flush=True)
if __name__=='__main__':main()
